func (s *server) dispatch(method string, p params) string {
	switch method {
	case "load_data":
		return s.loadData(p)
	case "list_functions":
		return functionList
	case "set_unstable_period":
		rideGen++
		return s.setUnstablePeriod(p)
	case "set_candle_settings":
		rideGen++
		return s.setCandleSettings(p)
	case "restore_candle_default_settings":
		rideGen++
		return s.restoreCandleDefaultSettings(p)
	case "eval_predicate":
		return evalPredicate(p)
	case "TA_GetRuntimeInfo":
		return runtimeInfo(p)
	case "fuzz_in_hash":
		return fuzzInHash(p)
	case "abstract_call":
		return s.absCall(p)
	case "abstract_get_lookback":
		return s.absLookback(p)
	case "abstract_get_display_shift":
		return s.absDisplayShift(p)
	case "abstract_for_each_func":
		return absForEachFunc()
	case "TA_GetFuncInfo":
		return absFuncInfo(p)
	case "TA_GetFuncAttributes":
		return absFuncAttributes(p)
	case "TA_GetInputParameterInfo":
		return absInputInfo(p)
	case "TA_GetOptInputParameterInfo":
		return absOptInputInfo(p)
	case "TA_GetOutputParameterInfo":
		return absOutputInfo(p)
	case "TA_FunctionDescriptionXML":
		return absDescriptionXML()
	case "stream_verify":
		return s.streamVerify(p)
	}
	return errorReply("Unknown method: " + method)
}

