	allOk := true
	peekAll := true
	peekReps := 0
	peekRejects := 0
	peekRepAll := true
	fillChecked := 0
	fillOk := true
	beg, nb := 0, 0
	diag := ""
	rangeChecked := 0
	rangeOk := true
