			if svXtierNe(v0, b0[P-1-beg], &zsign) {
				allOk = false
				if diag == "" {
					diag = fmt.Sprintf(`,"badBar":%d,"badOut":0,"where":"open"`, P-1)
				}
			}
			if svXtierNe(v1, b1[P-1-beg], &zsign) {
				allOk = false
				if diag == "" {
					diag = fmt.Sprintf(`,"badBar":%d,"badOut":1,"where":"open"`, P-1)
				}
			}
			va0, va1 := st.Value()
